function bottomUpTree(depth) {
  if (depth <= 0) return [null, null];
  const left = bottomUpTree(depth - 1);
  const right = bottomUpTree(depth - 1);
  return [left, right];
}

function itemCheck(tree) {
  if (tree === null) return 1;
  return 1 + itemCheck(tree[0]) + itemCheck(tree[1]);
}

function formatLine(a, b, c) {
  return `${a}\t${b}\t${c}\n`;
}

let output = "";

