    seqParts.push(line.trim());
  }
}
const seq = seqParts.join('').toUpperCase();
const n = seq.length;

function writeFreq(k) {
  const counts = new Map();
  const limit = n - k + 1;
  for (let i = 0; i < limit; i++) {
    const s = seq.substr(i, k);
    counts.set(s, (counts.get(s) || 0) + 1);
  }

  const arr = Array.from(counts.entries());
  arr.sort((a, b) => {
    const d = b[1] - a[1];
    return d !== 0 ? d : (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0);
  });

  let out = '';
  for (let i = 0; i < arr.length; i++) {
    const c = arr[i][1];
    out += arr[i][0] + ' ' + (c * 100 / limit).toFixed(3) + '\n';
  }
  process.stdout.write(out);
}

function countFragment(fragment) {
  const k = fragment.length;
  let count = 0;
  for (let i = 0, limit = n - k + 1; i < limit; i++) {
    if (seq.substr(i, k) === fragment) count++;
  }
  return count;
}

