const maxIter = 50;

const header = `P4\n${N} ${N}\n`;
const headerBuf = Buffer.from(header, 'ascii');

const rowBytes = (N + 7) >> 3;
const out = Buffer.allocUnsafe(headerBuf.length + rowBytes * N);
headerBuf.copy(out, 0);

let offset = headerBuf.length;

for (let y = 0; y < N; y++) {
  const ci = (2.0 * y / N) - 1.0;
  const row = Buffer.allocUnsafe(rowBytes);
  row.fill(0);

  for (let x = 0; x < N; x++) {
    const cr = (2.0 * x / N) - 1.5;

    let zr = 0.0, zi = 0.0;
    let zr2 = 0.0, zi2 = 0.0;
    let iter = 0;

    while (iter < maxIter && (zr2 + zi2) <= 4.0) {
      zi = 2.0 * zr * zi + ci;
      zr = zr2 - zi2 + cr;
      zr2 = zr * zr;
      zi2 = zi * zi;
      iter++;
    }

    if (iter === maxIter) {
      row[x >> 3] |= 0x80 >> (x & 7);
